using System.Globalization;
using System.Text.Json;
using System.Text.Json.Serialization;
using Htt.Infrastructure;
using Htt.SharedKernel;
using NpgsqlTypes;
using static Htt.Host.Api.MasterData.MasterDataSupport;
using static Htt.Host.Api.Sales.SalesSupport;
namespace Htt.Host.Api.MasterData;
public sealed record CollaborationCreate(Guid Id,string Kind,Guid CustomerId,Guid? BranchId,JsonElement Data);
public sealed record CustomerNote(string Text,string Visibility="TEAM");
public sealed record DisplayBoard(string Title,DateTimeOffset PlacedAt,Guid? ProductId=null,string? Description=null);
public sealed record VisitPosition([property:JsonRequired] decimal Latitude,[property:JsonRequired] decimal Longitude,[property:JsonRequired] decimal AccuracyMetres,[property:JsonRequired] DateTimeOffset CapturedAt);
public sealed record VisitCheckIn(VisitPosition CheckIn,string? Purpose=null);
public sealed record VisitCheckOut(VisitPosition CheckOut,string? Notes=null);
public sealed record CollaborationReason(string Reason);
public sealed record BranchCoordinates([property:JsonRequired] decimal Latitude,[property:JsonRequired] decimal Longitude,string Reason);
public sealed record CollaborationOperation(Guid OperationId,long Sequence,Guid Id,string Action,string? Kind=null,Guid? CustomerId=null,Guid? BranchId=null,long? Version=null,JsonElement? Data=null);
internal static class CollaborationEndpoints
{
 private static async Task<object> Value(CompanySession s,string sql,CancellationToken ct,params DbArg[] a)=>Element((await One(s,sql+"::text AS body",ct,a))["body"]!);
 private static Task<List<Dictionary<string,object?>>> Guard(CompanySession s,Guid id,bool write,CancellationToken ct)=>Read(s,"SELECT crm.require_collab(@id,@write)",ct,new DbArg("id",id),new DbArg("write",write));
 internal static JsonElement Normalize(string kind,string action,JsonElement data)
 {
  object normalized;T Decode<T>(){try{return data.Deserialize<T>(ApiJson.Options)??throw new JsonException();}catch(Exception e)when(e is JsonException or InvalidOperationException or NotSupportedException){throw new BusinessException("invalid_collaboration","Supply the documented collaboration payload.",422);}}
  VisitPosition Fix(VisitPosition? p){Check.That(p is not null&&p.Latitude is>=-90 and<=90&&p.Longitude is>=-180 and<=180&&p.AccuracyMetres is>=1 and<=1000&&decimal.Round(p.Latitude,7)==p.Latitude&&decimal.Round(p.Longitude,7)==p.Longitude&&p.CapturedAt>=DateTimeOffset.UtcNow.AddDays(-7)&&p.CapturedAt<=DateTimeOffset.UtcNow.AddMinutes(5),"position","Provide coordinates, accuracy 1..1000m and capture time within past 7 days.");return p!;}
  if(action=="DELETE")return JsonSerializer.SerializeToElement(new{},ApiJson.Options);
  if(action is"CANCEL"or"REMOVE"){var x=Decode<CollaborationReason>();normalized=new CollaborationReason(Check.Text(x.Reason,"reason",2000));}
  else if(kind=="NOTE"){var x=Decode<CustomerNote>();normalized=new CustomerNote(Check.Text(x.Text,"text",10000),Check.OneOf(x.Visibility,"visibility","TEAM","PRIVATE","OFFICE"));}
  else if(kind=="BOARD"){var x=Decode<DisplayBoard>();Check.That(x.PlacedAt!=default&&x.PlacedAt<=DateTimeOffset.UtcNow.AddMinutes(5)&&x.ProductId!=Guid.Empty,"placedAt","Valid placement date and product required.");normalized=x with{Title=Check.Text(x.Title,"title"),Description=Check.Optional(x.Description,"description",2000),PlacedAt=x.PlacedAt.ToUniversalTime()};}
  else if(kind=="VISIT"&&action=="CREATE"){var x=Decode<VisitCheckIn>();normalized=x with{CheckIn=Fix(x.CheckIn),Purpose=Check.Optional(x.Purpose,"purpose",2000)};}
  else if(kind=="VISIT"&&action=="CHECKOUT"){var x=Decode<VisitCheckOut>();normalized=x with{CheckOut=Fix(x.CheckOut),Notes=Check.Optional(x.Notes,"notes",2000)};}
  else throw new BusinessException("invalid_collaboration","Unsupported object operation.",422);
  return JsonSerializer.SerializeToElement(normalized,ApiJson.Options);
 }
 public static void Map(RouteGroupBuilder g)
 {
  g.MapGet("/crm/collaboration",List).WithMetadata(new Permission("crm.collaboration.read"));
  g.MapPost("/crm/collaboration",Create).WithMetadata(new Permission("crm.collaboration.read"));
  g.MapGet("/crm/collaboration/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>{await Guard(s,id,false,ct);await One(s,"SELECT id FROM crm.collaboration_objects WHERE company_id=@company AND id=@id AND state<>'DELETED'",ct,new DbArg("id",id));return Results.Ok(await Value(s,"SELECT crm.collab_json(@id)",ct,new DbArg("id",id)));}).WithMetadata(new Permission("crm.collaboration.read"));
  g.MapGet("/crm/collaboration/{id:guid}/history",async(Guid id,CompanySession s,CancellationToken ct)=>Results.Ok(await Value(s,"SELECT crm.collab_history(@id)",ct,new DbArg("id",id)))).WithMetadata(new Permission("crm.collaboration.read"));
  g.MapPut("/crm/collaboration/{id:guid}",async(Guid id,JsonElement x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>await Change(id,"UPDATE",x,h,s,idem,ct)).WithMetadata(new Permission("crm.collaboration.read"));
  g.MapDelete("/crm/collaboration/{id:guid}",async(Guid id,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>await Change(id,"DELETE",default,h,s,idem,ct)).WithMetadata(new Permission("crm.collaboration.read"));
  g.MapPost("/crm/collaboration/{id:guid}/checkout",async(Guid id,VisitCheckOut x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>await Change(id,"CHECKOUT",JsonSerializer.SerializeToElement(x,ApiJson.Options),h,s,idem,ct)).WithMetadata(new Permission("crm.visits.write"));
  g.MapPost("/crm/collaboration/{id:guid}/cancel",async(Guid id,CollaborationReason x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>await Change(id,"CANCEL",JsonSerializer.SerializeToElement(x),h,s,idem,ct)).WithMetadata(new Permission("crm.visits.write"));
  g.MapPost("/crm/collaboration/{id:guid}/remove",async(Guid id,CollaborationReason x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>await Change(id,"REMOVE",JsonSerializer.SerializeToElement(x),h,s,idem,ct)).WithMetadata(new Permission("crm.boards.write"));
  g.MapPost("/crm/mobile/devices/{device:guid}/collaboration-operations",Push).WithMetadata(new Permission("crm.mobile.sync"));
  g.MapGet("/crm/map/branches",MapBranches).WithMetadata(new Permission("crm.maps.read"));
  g.MapGet("/crm/branches/{branch:guid}/navigation",Navigation).WithMetadata(new Permission("crm.maps.read"));
  g.MapPut("/crm/branches/{branch:guid}/coordinates",Coordinates).WithMetadata(new Permission("crm.maps.manage"));
  g.MapPost("/crm/branches/{branch:guid}/geocode",QueueGeocode).WithMetadata(new Permission("crm.maps.manage"));
  g.MapGet("/crm/geocode-jobs/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>Results.Ok(await Value(s,"SELECT crm.geocode_view(@id)",ct,new DbArg("id",id)))).WithMetadata(new Permission("crm.maps.manage"));
  g.MapPost("/crm/geocode-jobs/{id:guid}/retry",async(Guid id,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{await Value(s,"SELECT crm.geocode_view(@id)",ct,new DbArg("id",id));return await Write("geocode_retry",id,new{id},h,s,idem,ct,async()=>{await Read(s,"SELECT crm.retry_geocode(@id)",ct,new DbArg("id",id));return await Value(s,"SELECT crm.geocode_view(@id)",ct,new DbArg("id",id));});}).WithMetadata(new Permission("crm.maps.manage"));
 }
 private static async Task<IResult> List(string? kind,Guid? customerId,Guid? branchId,Guid? ownerId,string? state,DateTimeOffset? from,DateTimeOffset? to,int? page,int? pageSize,CompanySession s,CancellationToken ct)
 {if(kind is not null)Check.OneOf(kind,"kind","NOTE","BOARD","VISIT");if(state is not null)Check.OneOf(state,"state","ACTIVE","DISPLAYED","REMOVED","OPEN","CLOSED","CANCELLED");Check.That(from is null||to is null||to>from,"dates","Use a nonempty [from,to) interval.");var(offset,size)=Page(page,pageSize);var rows=await Read(s,"SELECT crm.collab_json(o.id)::text AS body FROM crm.collaboration_objects o WHERE o.company_id=@company AND o.state<>'DELETED'AND crm.collab_visible(o.id)AND(@kind IS NULL OR o.kind=@kind)AND(@customer IS NULL OR o.customer_id=@customer)AND(@branch IS NULL OR o.branch_id=@branch)AND(@owner IS NULL OR o.owner_id=@owner)AND(@state IS NULL OR o.state=@state)AND(@from IS NULL OR o.created_at>=@from)AND(@to IS NULL OR o.created_at<@to)ORDER BY o.created_at DESC,o.id LIMIT @size OFFSET @offset",ct,new DbArg("kind",kind,NpgsqlDbType.Text),new DbArg("customer",customerId,NpgsqlDbType.Uuid),new DbArg("branch",branchId,NpgsqlDbType.Uuid),new DbArg("owner",ownerId,NpgsqlDbType.Uuid),new DbArg("state",state,NpgsqlDbType.Text),new DbArg("from",from?.ToUniversalTime(),NpgsqlDbType.TimestampTz),new DbArg("to",to?.ToUniversalTime(),NpgsqlDbType.TimestampTz),new DbArg("size",size),new DbArg("offset",offset));return Results.Ok(new{items=rows.Select(x=>Element(x["body"]!)),page=page??1,pageSize=size});}
 private static async Task<IResult> Create(CollaborationCreate x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {Check.That(x.Id!=Guid.Empty&&x.CustomerId!=Guid.Empty&&x.BranchId!=Guid.Empty,"id","Object/customer IDs required.");Check.OneOf(x.Kind,"kind","NOTE","BOARD","VISIT");await Customer(h,s,x.CustomerId,ct);await Read(s,"SELECT crm.require_collab_customer(@customer)",ct,new DbArg("customer",x.CustomerId));await Read(s,"SELECT crm.require_mobile(@cap)",ct,new DbArg("cap",Cap(x.Kind)));var data=Normalize(x.Kind,"CREATE",x.Data);return await Write("create",x.Id,new{x.Id,x.Kind,x.CustomerId,x.BranchId,data},h,s,idem,ct,()=>Command(s,x.Id,x.Kind,x.CustomerId,x.BranchId,"CREATE",null,data,ct),201);}
 private static string Cap(string kind)=>kind switch{"NOTE"=>"crm.notes.write","BOARD"=>"crm.boards.write",_=>"crm.visits.write"};
 private static async Task<IResult> Change(Guid id,string action,JsonElement input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Guard(s,id,true,ct);var kind=(string)(await One(s,"SELECT kind FROM crm.collaboration_objects WHERE company_id=@company AND id=@id",ct,new DbArg("id",id)))["kind"]!;var data=Normalize(kind,action,input);var version=Version(h);return await Write(action.ToLowerInvariant(),id,new{id,version,data},h,s,idem,ct,()=>Command(s,id,kind,null,null,action,version,data,ct));}
 private static Task<object> Command(CompanySession s,Guid id,string kind,Guid? customer,Guid? branch,string action,long? version,JsonElement data,CancellationToken ct)=>Value(s,"SELECT crm.collab_command(@id,@kind,@customer,@branch,@action,@v,@data)",ct,new DbArg("id",id),new DbArg("kind",kind),new DbArg("customer",customer,NpgsqlDbType.Uuid),new DbArg("branch",branch,NpgsqlDbType.Uuid),new DbArg("action",action),new DbArg("v",version,NpgsqlDbType.Bigint),new DbArg("data",data.GetRawText(),NpgsqlDbType.Jsonb));
 private static async Task<IResult> Push(Guid device,CollaborationOperation x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Read(s,"SELECT crm.require_mobile_device(@device),crm.require_mobile('crm.collaboration.read')",ct,new DbArg("device",device));Check.That(x.OperationId!=Guid.Empty&&x.Id!=Guid.Empty&&x.Sequence>0,"operation","Stable IDs and positive sequence required.");Check.OneOf(x.Action,"action","CREATE","UPDATE","DELETE","CHECKOUT","CANCEL","REMOVE");var kind=x.Kind;if(x.Action=="CREATE"){Check.OneOf(kind,"kind","NOTE","BOARD","VISIT");Check.That(x.CustomerId is not null&&x.CustomerId!=Guid.Empty,"customerId","Target customer required.");await Customer(h,s,x.CustomerId!.Value,ct);await Read(s,"SELECT crm.require_collab_customer(@customer)",ct,new DbArg("customer",x.CustomerId.Value));await Read(s,"SELECT crm.require_mobile(@cap)",ct,new DbArg("cap",Cap(kind!)));}else{await Guard(s,x.Id,true,ct);kind=(string)(await One(s,"SELECT kind FROM crm.collaboration_objects WHERE company_id=@company AND id=@id",ct,new DbArg("id",x.Id)))["kind"]!;Check.That(x.Version>0,"version","Expected version required.");}var data=Normalize(kind!,x.Action,x.Data??default);var request=new{domain="COLLABORATION",id=x.Id,kind,customerId=x.CustomerId,branchId=x.BranchId,action=x.Action,version=x.Version,data};return await Write("push",x.Id,new{device,x.OperationId,x.Sequence,request},h,s,idem,ct,()=>Value(s,"SELECT crm.collab_push(@device,@op,@seq,@data)",ct,new DbArg("device",device),new DbArg("op",x.OperationId),new DbArg("seq",x.Sequence),new DbArg("data",Json(request),NpgsqlDbType.Jsonb)));}
 private static async Task<IResult> Coordinates(Guid branch,BranchCoordinates x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Read(s,"SELECT crm.require_branch(@branch,true)",ct,new DbArg("branch",branch));Check.That(x.Latitude is>=-90 and<=90&&x.Longitude is>=-180 and<=180&&decimal.Round(x.Latitude,7)==x.Latitude&&decimal.Round(x.Longitude,7)==x.Longitude,"coordinates","Use valid coordinates with at most 7 decimals.");var reason=Check.Text(x.Reason,"reason",2000);var version=Version(h);return await Write("coordinates",branch,new{branch,version,x.Latitude,x.Longitude,reason},h,s,idem,ct,async()=>{await Read(s,"SELECT crm.set_branch_coordinates(@branch,@v,@lat,@lng,@reason)",ct,new DbArg("branch",branch),new DbArg("v",version),new DbArg("lat",x.Latitude),new DbArg("lng",x.Longitude),new DbArg("reason",reason));return new{branchId=branch,branchVersion=version,source="MANUAL"};});}
 private static async Task<IResult> QueueGeocode(Guid branch,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Read(s,"SELECT crm.require_branch(@branch,true)",ct,new DbArg("branch",branch));var version=Version(h);return await Write("geocode",branch,new{branch,version},h,s,idem,ct,async()=>{var id=(Guid)(await One(s,"SELECT crm.queue_geocode(@branch,@v)AS id",ct,new DbArg("branch",branch),new DbArg("v",version)))["id"]!;return await Value(s,"SELECT crm.geocode_view(@id)",ct,new DbArg("id",id));},202);}
 private static async Task<IResult> MapBranches(Guid? customerId,string? state,string? status,string? geocodeState,bool? hasBoards,string? q,Guid? salesperson,decimal? south,decimal? north,decimal? west,decimal? east,int? page,int? pageSize,CompanySession s,CancellationToken ct)
 {if(state is not null)Check.OneOf(state,"state","ACT","NSW","NT","QLD","SA","TAS","VIC","WA");if(status is not null)Check.OneOf(status,"status","ACTIVE","ON_HOLD","INACTIVE");if(geocodeState is not null)Check.OneOf(geocodeState,"geocodeState","LOCATED","UNLOCATED","STALE","PENDING","FAILED");q=Check.Optional(q,"q",100);var n=new[]{south,north,west,east}.Count(x=>x is not null);Check.That(n==0||n==4&&south>=-90&&north<=90&&south<=north&&west>=-180&&west<=180&&east>=-180&&east<=180,"bounds","Supply complete valid bounding box; west>east crosses the date line.");var(offset,size)=Page(page,pageSize);var filter=new{customerId,state,status,geocodeState,hasBoards,q,salesperson,south,north,west,east,offset,size};return Results.Ok(await Value(s,"SELECT crm.map_branches(@filter)",ct,new DbArg("filter",Json(filter),NpgsqlDbType.Jsonb)));}
 private static async Task<IResult> Navigation(Guid branch,string? provider,CompanySession s,CancellationToken ct)
 {provider=Check.OneOf(provider??"GOOGLE","provider","GOOGLE","APPLE");await Read(s,"SELECT crm.require_branch(@branch,false)",ct,new DbArg("branch",branch));var b=await One(s,"SELECT b.id,b.version,concat_ws(', ',b.address_line1,b.suburb,b.state,b.postcode,b.country)AS address,g.latitude,g.longitude,g.source,g.place_id FROM crm.customer_branches b LEFT JOIN crm.branch_geocodes g ON g.company_id=b.company_id AND g.branch_id=b.id AND g.branch_version=b.version AND(g.expires_at IS NULL OR g.expires_at>now())WHERE b.company_id=@company AND b.id=@branch",ct,new DbArg("branch",branch));if(provider=="APPLE"&&b["source"]is string source&&source=="GOOGLE")throw new BusinessException("map_provider_conflict","Use Google Maps for Google-derived coordinates.",409);var destination=b["latitude"]is decimal lat&&b["longitude"]is decimal lng?lat.ToString(CultureInfo.InvariantCulture)+","+lng.ToString(CultureInfo.InvariantCulture):(string)b["address"]!;var uri=provider=="GOOGLE"?"https://www.google.com/maps/dir/?api=1&destination=":"https://maps.apple.com/?daddr=";uri+=Uri.EscapeDataString(destination);if(provider=="GOOGLE"&&b["place_id"]is string place)uri+="&destination_place_id="+Uri.EscapeDataString(place);return Results.Ok(new{branchId=branch,branchVersion=b["version"],provider,url=uri,usesCoordinates=b["latitude"]is not null});}
 private static async Task<IResult> Write(string action,Guid id,object input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct,Func<Task<object>> run,int status=200)
 {var response=await idem.ExecuteAsync("POST /crm/collaboration/"+action,h.Request.Headers["Idempotency-Key"].ToString(),Json(input),async()=>{var result=await run();await Sql.AuditAsync(s,"crm.collaboration_"+action,"crm_collaboration",id,h.TraceIdentifier,ct);return ApiJson.Stored(result,status);},ct);return ApiJson.Result(response);}
}
